
const library=document.querySelector('[data-library]');
if(library){let category='all';const search=document.querySelector('#library-search');const cards=[...library.querySelectorAll('[data-category]')];const apply=()=>{const q=search.value.toLowerCase().trim();let count=0;cards.forEach(card=>{const visible=(category==='all'||card.dataset.category.split(' ').includes(category))&&card.textContent.toLowerCase().includes(q);card.hidden=!visible;if(visible)count++});document.querySelector('#result-count').textContent=`${count} ${count===1?'item':'items'}`;document.querySelector('#empty-results').hidden=count!==0};document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));apply()}));search.addEventListener('input',apply);apply()}
const form=document.querySelector('#inquiry-preview');if(form){form.addEventListener('submit',event=>{event.preventDefault();const status=document.querySelector('#form-status');status.hidden=false;status.textContent='Preview complete. Nothing was sent or saved. The live form will send your inquiry to Noah.';status.focus()})}
